function shop(){open(`<button class="close" onclick="document.getElementById('modal').classList.remove('open')">×</button><div class="eyebrow">Seruni Spirit Shop · ${state.shells} shells</div><h1>Small things for the road</h1><p>Made with care by the village keeper. Shells are earned by meeting trainers and welcoming new friends.</p><div class="journal-entry"><span class="emoji">🔮</span><div><strong>Sea-glass bead · 3 shells</strong><small>Offer a bead to invite a spirit into your party. You have ${state.orbs}.</small><button class="primary shopbuy" id="buyBead">Buy one bead</button></div></div><div class="journal-entry"><span class="emoji">🌿</span><div><strong>Healing herb · 4 shells</strong><small>Restore 18 energy to your first companion. You have ${state.remedies}.</small><button class="primary shopbuy" id="buyHerb">Buy one herb</button></div></div><p id="shopMessage" class="modal-foot">A gentle trade keeps the island stories travelling.</p>`);$('buyBead').onclick=()=>purchase('bead');$('buyHerb').onclick=()=>purchase('herb')}
function purchase(item){const price=item==='bead'?3:4;if(state.shells<price){toast('Not enough shells yet. Meet a trainer for a friendly challenge.');return}state.shells-=price;if(item==='bead')state.orbs++;else state.remedies++;updateUI();shop();toast(item==='bead'?'A sea-glass bead joins your satchel.':'A healing herb joins your satchel.')}
function talkTrainer(npc){open(`<div class="eyebrow">Wayfinder trainer</div><h1>${npc.name}</h1><p>${npc.defeated?`“Well met, ${state.train}! Keep listening to the island.”`:`“Hello, ${state.train}! I travel with ${npc.spirit}. Would you like a friendly training match?”`}</p><div class="battle-actions">${npc.defeated?'<button class="primary" id="talkClose">Lovely, thanks</button>':'<button class="primary" id="challengeBtn">⚔ Friendly match</button><button class="runbtn" id="talkClose">Maybe later</button>'}</div>`);const closeTalk=()=>{$('modal').classList.remove('open')};$('talkClose').onclick=closeTalk;if(!npc.defeated)$('challengeBtn').onclick=()=>battle(npc.spirit,npc)}
function interact(){if(!state.started){welcome();return}if(state.battle)return;const npc=nearbyTrainer();if(npc){talkTrainer(npc);return}if(nearTile('H')){shop();return}toast('A warm breeze rustles the leaves. You hear a distant spirit song.')}

