arty[i]];updateUI();partyMenu()});$('dialog').querySelectorAll('[data-heal]').forEach(b=>b.onclick=()=>{const m=state.party[+b.dataset.heal];if(!m||!state.remedies||m.hp>=m.maxhp)return;state.remedies--;const amount=Math.min(18,m.maxhp-m.hp);m.hp+=amount;updateUI();partyMenu();toast(`${m.name} recovered ${amount} energy.`)});$('dialog').querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const m=state.party[+b.dataset.upgrade],cost=5+(m.level||3)*2;if(!m||state.shells<cost)return;state.shells-=cost;m.level=(m.level||3)+1;m.maxhp+=5;m.hp=Math.min(m.maxhp,m.hp+5);m.moves=m.moves.map(move=>[move[0],move[1],move[2]+1]);updateUI();partyMenu();toast(`${m.name} grew to level ${m.level}!`)});paintArt($('dialog'))}
