+$('partyBtn').onclick=partyMenu;
 $('bagBtn').onclick=()=>{open(`<button class="close" onclick="document.getElementById('modal').classList.remove('open')">×</button><div class="eyebrow">Wayfinder satchel</div><h1>Little offerings</h1><div class="journal-entry"><span class="emoji">🔮</span><div><strong>Sea-glass beads × ${state.orbs}</strong><small>Offer a bead to a spirit you meet. Kindness works better than force.</small></div></div><div class="journal-entry"><span class="emoji">🌿</span><div><strong>Healing herbs × ${state.remedies}</strong><small>Restore 18 energy to your first companion.</small><button class="primary shopbuy" id="useHerb" ${state.remedies<1||!state.party.length?'disabled':''}>Use healing herb</button></div></div><p>Beads are gifts, not traps. If someone would rather be alone, respect their answer and meet them again another day.</p><button class="primary" id="bagclose">Close satchel</button>`);$('useHerb').onclick=()=>{if(!state.remedies||!state.party.length)return;state.remedies--;const m=state.party[0];m.hp=Math.min(m.maxhp,m.hp+18);updateUI();$('bagBtn').click();toast(`${m.name} feels refreshed.`)};$('bagclose').onclick=close};
 function guide(){let entries=[...starters,...Object.values(mons)].filter(m=>state.seen.includes(m.name));open(`<button class="close" onclick="document.getElementById('modal').classList.remove('open')">×</button><div class="eyebrow">Field guide · ${state.seen.length} stories collected</div><h1>Island bestiary</h1><p>Folklore travels across shorelines. These gentle new friends carry stories that belong to living cultures.</p><div class="tabs"><button class="tab on" data-tab="all">All stories</button><button class="tab" data-tab="indonesia">Indonesia</button><button class="tab" data-tab="malaysia">Malaysia</button><button class="tab" data-tab="singapore">Singapore</button></div><div class="journal-list">${entries.length?entries.map(m=>`<div class="journal-entry">${art(m.name)}<div><strong>${m.name}</strong><small>${m.type} spirit · ${areas.find(a=>a.creatures.includes(m.name))?.sub||'Your first companion'}</small><small style="font:400 10px 'DM Sans';line-height:1.4;margin-top:5px;color:#708078">${m.lore}</small></div></div>`).join(''):'<div class="empty-party">No stories collected yet. Follow the path, and keep a kind heart.</div>'}</div><p class="modal-foot">Folklore varies by community and storyteller. This game is an original, respectful interpretation—not a definitive cultural account.</p>`);$('dialog').querySelectorAll('[data-tab]').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('on'));t.classList.add('on');if(t.dataset.tab!=='all')toast('Stories are gathered across the whole archipelago.')})}
 $('guideBtn').onclick=guide;$('journalOpen').onclick=guide;
 $('soundBtn').onclick=()=>{state.sound=!state.sound;$('soundBtn').textContent=state.sound?'♫':'♪';toast(state.sound?'Island sounds on':'Island sounds off')};

