python3 - <<'PY'
import re
s=open('index.html').read()
blocks=re.findall(r"map:makeMap\(\[(.*?)\]\)",s)
maps=[]
for b in blocks:
 rows=re.findall(r"'([^']*)'",b)
 maps.append([r.ljust(16,'~')[:16] for r in rows])
W=len(maps)*16
walk=set('s.t=P')
def tile(x,y):
 if y==5 and any(st<=x<=st+5 for st in [13,29,45,61]): return '='
 return maps[x//16][y][x%16] if 0<=x<W and 0<=y<12 else '~'
start=(7,5)
q=[start]; seen={start}
for x,y in q:
 for n in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
  if n not in seen and tile(*n) in walk: seen.add(n);q.append(n)
print('reachable region count',sorted({x//16 for x,y in seen}))
for x in [15,16,31,32,47,48,63,64]:
 print('seam',x,[(tile(x,y),tile(x+1,y)) for y in range(12) if tile(x,y) in walk and tile(x+1,y) in walk])
for i in range(len(maps)):
 cells=[(x,y) for x in range(i*16,(i+1)*16) for y in range(12) if tile(x,y) in walk]
 print('region',i,'reachable tiles',sum(p in seen for p in cells),'/',len(cells))
