inject=r'''
async function browserChecks(){
 const results=[];const check=(name,ok,detail='')=>results.push(`${ok?'PASS':'FAIL'} ${name}${detail?': '+detail:''}`);
 try{
  const W=areas.length*16, queue=[[7,5]], seen=new Set(['7,5']);
  for(let n=0;n<queue.length;n++){const [x,y]=queue[n];for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=`${nx},${ny}`;if(!seen.has(k)&&walkable(tileAt(nx+.5,ny+.5))){seen.add(k);queue.push([nx,ny])}}}
  const all=[];for(let x=0;x<W;x++)for(let y=0;y<12;y++)if(walkable(tileAt(x+.5,y+.5)))all.push([x,y]);
  const allReached=all.every(([x,y])=>seen.has(`${x},${y}`));
  const trainersReached=trainers.every(n=>seen.has(`${Math.floor(n.area*16+n.x)},${Math.floor(n.y)}`));
  check('exact map connectivity',allReached&&trainersReached,`${seen.size} reachable walk tiles; ${trainers.length} trainers ${trainersReached?'reachable':'not all reachable'}`);
 }catch(e){check('exact map connectivity',false,e.message)}
 try{
  startGame(starters[0]);state.party.push({...mons.Kantilume,hp:10,maxhp:30,level:2});
  partyMenu();$('dialog').querySelector('[data-down="0"]').click();
  const moved=state.party[0].name==='Kantilume';$('dialog').querySelector('[data-up="1"]').click();
  check('party ordering',moved&&state.party[0].name==='Bara','move down and restore lead');
  state.party[0].hp=10;state.remedies=2;partyMenu();$('dialog').querySelector('[data-heal="0"]').click();
  check('companion healing',state.party[0].hp===28&&state.remedies===1,`${state.party[0].hp} HP, ${state.remedies} herbs left`);
  state.shells=30;const maxBefore=state.party[0].maxhp,powerBefore=state.party[0].moves[0][2];partyMenu();$('dialog').querySelector('[data-upgrade="0"]').click();
  check('companion upgrade',state.party[0].level===4&&state.party[0].maxhp===maxBefore+5&&state.party[0].moves[0][2]===powerBefore+1&&state.shells===19,`level ${state.party[0].level}, ${state.shells} shells left`);
 }catch(e){check('companion management',false,e.stack||e.message)}
 try{
  const names=[...starters,...Object.values(mons)].map(m=>m.name);let painted=true;
  for(const name of names){const c=art(name);$('dialog').append(c);paintArt(c.parentElement);const pix=c.getContext('2d').getImageData(0,0,c.width,c.height).data;let visible=false;for(let i=3;i<pix.length;i+=4)if(pix[i]){visible=true;break}if(!visible)painted=false;c.remove()}
  check('custom sprite rendering',painted,`${names.length} unique sprite canvases painted`);
 }catch(e){check('custom sprite rendering',false,e.message)}
 try{
  const x=state.player.x;document.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true,cancelable:true}));const keyboardMoved=state.player.x===x+1;
  const y=state.player.y,btn=document.querySelector('[data-dir="down"]');btn.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true,pointerType:'touch'}));
  check('keyboard and touch-pad movement',keyboardMoved&&state.player.y===y+1,`keyboard=${keyboardMoved}, d-pad=${state.player.y===y+1}`);
 }catch(e){check('keyboard and touch-pad movement',false,e.message)}
 try{
  battle('Tuyuli');const wildOpen=!!state.battle&&$('dialog').textContent.includes('Tuyuli');$('runBtn').click();
  state.area=0;state.player={x:3.5,y:3.5};interact();$('challengeBtn').click();state.battle.foe.hp=1;const shells=state.shells;$('dialog').querySelector('[data-move="0"]').click();
  check('wild and trainer encounter flow',wildOpen&&!state.battle&&trainers[0].defeated&&state.shells===shells+5,'wild retreat and trainer victory');
 }catch(e){check('wild and trainer encounter flow',false,e.stack||e.message)}
 const metrics={viewport:`${innerWidth}x${innerHeight}`,shell:`${Math.round(document.querySelector('.shell').getBoundingClientRect().width)}x${Math.round(document.querySelector('.shell').getBoundingClientRect().height)}`,actionOverflow:document.querySelector('.action-grid').scrollWidth>document.querySelector('.action-grid').clientWidth};
 check('responsive layout',!metrics.actionOverflow,JSON.stringify(metrics));
 const out=document.createElement('pre');out.id='browser-results';out.textContent=results.join('\n');document.body.append(out);
}
browserChecks();
'''
